 57	
 58	/**
 59	 * @author Vitaliy Fedoriv
 60	 */
 61	
 62	@RestController
 63	@CrossOrigin(exposedHeaders = "errors, content-type")
 64	@RequestMapping("/api")
 65	public class OwnerRestControllerV1 implements OwnersApi {
 66	
 67	    /** Maximum number of owners a single city may contain; creating another owner there is rejected. */
 68	    static final int CITY_CAPACITY = 50;
 69	
 70	    /** Maximum number of owners that may be created per (business-day adjusted) registration date; further creates are rejected. */
 71	    static final int DAILY_OWNER_LIMIT = 100;
 72	
 73	    private final ClinicService clinicService;
 74	
 75	    private final OwnerMapper ownerMapper;
 76	
 77	    private final PetMapper petMapper;
 78	
 79	    private final VisitMapper visitMapper;
 80	
 81	    public OwnerRestControllerV1(ClinicService clinicService,
 82	                                 OwnerMapper ownerMapper,
 83	                                 PetMapper petMapper,
 84	                                 VisitMapper visitMapper) {
 85	        this.clinicService = clinicService;
 86	        this.ownerMapper = ownerMapper;
 87	        this.petMapper = petMapper;
 88	        this.visitMapper = visitMapper;
 89	    }
 90	
 91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
 92	    @Override
 93	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
 94	        Collection<Owner> owners;
 95	        if (lastName != null) {
 96	            owners = this.clinicService.findOwnerByLastName(lastName);
 97	        } else {
 98	            owners = this.clinicService.findAllOwners();
 99	        }
100	        if (owners.isEmpty()) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
109	        Owner owner = this.clinicService.findOwnerById(ownerId);
110	        if (owner == null) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
119	        List<String> missingFields = RequiredOwnerFields.missingFields(ownerFieldsDto);
120	        if (!missingFields.isEmpty()) {
121	            throw new MissingRequiredFieldsException(missingFields);
122	        }
123	        HttpHeaders headers = new HttpHeaders();
124	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
125	        String telephone = OwnerTelephone.normalize(ownerFieldsDto.getTelephone());
126	        if (this.clinicService.ownerTelephoneExists(telephone)) {
127	            throw new DuplicateTelephoneException(telephone);
128	        }
129	        String address = AddressNormalizer.normalize(ownerFieldsDto.getAddress());
130	        owner.setAddress(address);
131	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
132	        if (!sharesHousehold
133	            && this.clinicService.ownerHouseholdExists(ownerFieldsDto.getLastName(), address)) {
134	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), address);
135	        }
136	        if (this.clinicService.countOwnersInCity(ownerFieldsDto.getCity()) >= CITY_CAPACITY) {
137	            throw new CityCapacityExceededException(ownerFieldsDto.getCity(), CITY_CAPACITY);
138	        }
139	        LocalDate registrationDate = BusinessDays.rollForward(
140	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
141	        if (this.clinicService.countOwnersRegisteredOn(registrationDate) >= DAILY_OWNER_LIMIT) {
142	            throw new DailyOwnerLimitExceededException(DAILY_OWNER_LIMIT);
143	        }
144	        if (sharesHousehold) {
145	            this.clinicService.joinHousehold(owner);
146	        }
147	        owner.setTelephone(telephone);
148	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
149	        owner.setRegistrationDate(registrationDate);
150	        this.clinicService.saveOwner(owner);
151	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
152	        headers.setLocation(UriComponentsBuilder.newInstance()
153	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
154	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
155	    }
156	
157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Override
159	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
160	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
161	        if (currentOwner == null) {
162	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
163	        }
164	        String telephone = OwnerTelephone.normalize(ownerFieldsDto.getTelephone());
165	        currentOwner.setAddress(ownerFieldsDto.getAddress());
166	        currentOwner.setCity(ownerFieldsDto.getCity());
167	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
168	        currentOwner.setLastName(ownerFieldsDto.getLastName());
169	        currentOwner.setTelephone(telephone);
170	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
171	        if (ownerFieldsDto.getRegistrationDate() != null) {
172	            currentOwner.setRegistrationDate(BusinessDays.rollForward(ownerFieldsDto.getRegistrationDate()));
173	        }
174	        this.clinicService.saveOwner(currentOwner);
175	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
176	    }
177	
178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Transactional
180	    @Override
181	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
182	        Owner owner = this.clinicService.findOwnerById(ownerId);
183	        if (owner == null) {
184	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
185	        }
186	        this.clinicService.deleteOwner(owner);
187	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
188	    }
